def _switch_almt(self, name):
    if self.almt_dirty and not self.confirm_discard():
        self.almt_combo.set(split(self.almt_path)[-1] if self.almt_path else '')
        return
    self.load_almt(name)

_ai_block.original_source:
def _ai_block(self):
    """AIPM block (chr/ai/<id>.bin) for the selected move's input selector, or None."""
    if self.move is None or not self._battle_base_table() or not self.root_data:
        return None
    entry = battleinput.MOVE_CONTROLS.get(self.move.id & 0xFF)
    if entry is None:
        return None
    cid = split(self.almt_path)[-1][:-4]
    if cid not in self._ai_profiles:
        path = battleai.AIPM_PATH.format(cid=cid)
        try:
            self._ai_profiles[cid] = battleai.parse_aipm(self.root_data.read(path)) \
                if self.root_data.exists(path) else None
        except (ValueError, KeyError, OSError):
            self._ai_profiles[cid] = None
    prof = self._ai_profiles[cid]
    return prof.for_selector(entry[1]) if prof else None

_move_xref.original_source:
def _move_xref(self):
    """Read-only, session-local BIN/Koma/ALMT references."""
    if self.root_data is None:
        return None
    if self._move_xrefs is None and not self._move_xrefs_error:
        try:
            self._move_xrefs = movelinks.MoveLinks(self.root_data)
        except (OSError, ValueError, KeyError) as exc:
            self._move_xrefs_error = str(exc)
    return self._move_xrefs

_move_source_form.original_source:
def _move_source_form(self):
    if not self.almt_path:
        return None, None
    member = split(self.almt_path)[-1]
    stem = member[:-4] if member.endswith('.amt') else ''
    if stem in roster.BATTLE_IDS:
        return stem, member
    for size in (2, 3):
        tail = f'_{size}'
        if stem.endswith(tail) and stem[:-len(tail)] in roster.SUPPORT_IDS:
            return stem[:-len(tail)], member
    return None, None

_move_control_and_title.original_source:
def _move_control_and_title(self, move):
    form, member = self._move_source_form()
    if not form:
        return ''
    label = (battleinput.control_for(move.id) or '') if form in roster.BATTLE_IDS else ''
    # The Roster tree already shows the original BIN-backed move titles.
    # This legacy Moves Treeview is deliberately hidden in Roster mode but
    # remains the selection model for Timeline/Undo. Never decompress the
    # same ChrArc ALMT once per row just to label a *hidden* list:
    # MoveLinks.text_for_move -> _source_ids -> DataRoot.read decompresses
    # the full nested DSCP payload for every row (an observable UI freeze).
    if getattr(self, 'roster_browser', None) is not None:
        return label or (f'Support ({member})' if form in roster.SUPPORT_IDS else '')
    svc = self._move_xref()
    if svc:
        title = svc.text_for_move(form, move.id, almt_member=member)
        if title and title.display_title:
            return f'{label} - {title.display_title}' if label else title.display_title
    return label or (f'Support ({member})' if form in roster.SUPPORT_IDS else '')

