def _move_row(self, i):
    m = self.almt.moves[i]
    if self.moves_tree.exists(str(i)):
        self.moves_tree.item(str(i), values=(i, hx(m.id, 6), m.duration, '⟳' if m.flags & 1 else '', self._move_control_and_title(m)))

